import{z as A,x as d,o as r,c as B,q as o,j as n,D as l,d as E,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"检索投毒防御","description":"","frontmatter":{"title":"检索投毒防御","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/retrieval-poisoning-defense.md","filePath":"llm/retrieval-poisoning-defense.md","lastUpdated":1791413859000}'),p={name:"llm/retrieval-poisoning-defense.md"};function m(f,a,D,h,u,T){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="检索投毒防御" tabindex="-1">检索投毒防御 <a class="header-anchor" href="#检索投毒防御" aria-label="Permalink to &quot;检索投毒防御&quot;">​</a></h1><div class="epigraph"><p>索引可写，对手就愿意写。少量特制文档可以在向量空间里抢走特定查询的 Top-k，阅读器会把毒块当证据。</p><footer>—— 对照 PoisonedRAG 一类对稠密检索投毒的研究；防御走校验与隔离，不公开投毒配方</footer></div><p><a href="/llm/rag-vs-finetune">上一课</a>把可更新集合选成知识住所。可更新即攻击面。本课写检索投毒的<strong>防御评测与工程边界</strong>。缺口不是再讲 InfoNCE，而是：召回率高可以来自毒块。课程在此结束；下一课程多模态生成不再默认检索集合可信。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对手若能向语料库插入或篡改文档（网页抓取、共享知识库、供应链），可以把嵌入推到目标查询附近，使 Top-k 被占。阅读器越「忠于上下文」，越会复述毒块——忠实度指标会反向奖励中招。<span class="marginnote">直觉类比：往图书馆塞进一本封面做得最像「权威答案」的假书。检索员按「哪本最像问题」取书，拿到的就是它；而阅读员越诚实、越习惯照书念，就越会把假书内容当真话输出。两个各自「称职」的环节叠在一起，恰好把毒送进答案——这是检索系统特有的失败方式。</span>与<a href="/llm/indirect-injection">间接注入</a> 同构：检索块是不可信输入。与训练数据投毒不同：不必碰权重。</p>',5)),(r(),n(s,null,{default:l(()=>[i(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AF%B9%E6%89%8B%E5%8F%AF%E5%86%99%E7%B4%A2%E5%BC%95%22%5D%20--%3E%20B%5B%22%E6%8F%92%E5%85%A5%E7%89%B9%E5%88%B6%E6%96%87%E6%A1%A3%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%B5%8C%E5%85%A5%E9%9D%A0%E8%BF%91%E7%9B%AE%E6%A0%87%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20C%20--%3E%20D%5B%22Top-k%20%E8%A2%AB%E6%AF%92%E5%9D%97%E5%8D%A0%E6%8D%AE%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%BF%A0%E5%AE%9E%E9%98%85%E8%AF%BB%E5%99%A8%E5%A4%8D%E8%BF%B0%E6%AF%92%E5%9D%97%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%94%99%E8%AF%AF%E7%AD%94%E6%A1%88%E8%BF%98%E5%B8%A6%E5%BC%95%E7%94%A8%20%E6%98%BE%E5%BE%97%E6%9B%B4%E5%8F%AF%E4%BF%A1%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"公开描述具体如何构造毒向量，会变成教程。评测只定义：在隔离库上插入标记过的对抗文档，看目标查询是否被劫持、以及防御后是否恢复。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"本课不提供投毒文档的写法或绕过过滤的特征。只讨论检测、隔离、交叉验证与权限。")],-1)),a[5]||(a[5]=e("h2",{id:"方法",tabindex:"-1"},[E("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[6]||(a[6]=e("p",null,[E("防御层叠：写入鉴权与审核；来源信誉；新文档隔离观察；检索结果与独立通道交叉（BM25 与稠密不一致时降权）；阅读器提示「块可能不可信」并要求多源一致才断言；敏感查询走人审。"),e("span",{class:"marginnote"},"「劫持率」和「误杀率」是一对必须一起看的数：劫持率是毒块仍占进 Top-k 的比例，误杀率是防御把合法文档错误降权的比例。只压劫持率会造出一台见谁都拦的安检机——系统「安全」了，检索也废了。评测两者都要报，并给出你选的平衡点。"),E("检测：近重复簇、异常高的查询–文档分、同一作者短时间占满多查询的 Top-k。评测用内部红队库，报告劫持率与误杀率（合法文档被降权）。")],-1)),(r(),n(s,null,{default:l(()=>[i(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22%E5%86%99%E5%85%A5%22%5D%20--%3E%20AUT%5B%22%E9%89%B4%E6%9D%83%E4%B8%8E%E9%9A%94%E7%A6%BB%22%5D%0A%20%20AUT%20--%3E%20RET%5B%22%E5%A4%9A%E9%80%9A%E9%81%93%E6%A3%80%E7%B4%A2%22%5D%0A%20%20RET%20--%3E%20CON%5B%22%E5%A4%9A%E6%BA%90%E4%B8%80%E8%87%B4%E6%89%8D%E6%96%AD%E8%A8%80%22%5D%0A%20%20CON%20--%3E%20HUM%5B%22%E6%95%8F%E6%84%9F%E4%BA%BA%E5%AE%A1%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稠密空间连续，小扰动可改变近邻。稀疏词法对字面异常更敏感，故混合通道提高发现不一致性的机会，不是为了刷召回。阅读器无怀疑地最大化 \\(p(y\\mid x,\\mathrm{blocks})\\) 时，毒块就是最强条件。<span class="marginnote">常见误区：以为「换一个更强的嵌入模型」就能免疫投毒。嵌入空间是连续的，攻击者总能朝目标查询的方向微调文档——模型升级只是抬高了门槛，没有关闭这扇门。根本的防御动作是在打分之外引入<strong>来源</strong>维度：谁写入的、有没有审核、其他通道是否佐证，这些是嵌入模型本身给不了的。</span>防御必须在目标函数外加「来源」变量，不能只加更好的嵌入模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>内网只读镜像、无用户生成内容时，投毒面小但仍有供应链（供应商文档）。公开互联网 RAG 面最大。检索课结束。下一课从像素如何进生成模型讲起，默认文本索引的教训已经学完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可写索引可被劫持；忠实阅读器会放大毒块。</li><li>鉴权、隔离、多通道交叉、多源一致、敏感人审。</li><li>评测劫持率与误杀；不公开投毒配方。</li><li>出处：稠密检索投毒现象的公开研究（PoisonedRAG 等）；间接注入课。</li></ul>',6))])}const c=A(p,[["render",m]]);export{F as __pageData,c as default};
